INSERT INTO comprobantes (
    numero_comprobante, codigo_punto_expedicion, punto_expedicion_fiscal,
    codigo_sucursal, establecimiento_fiscal, codigo_serie, serie_fiscal,
    codigo_tipo_comprobante, codigo_timbrado, numero_timbrado_fiscal,
    inicio_vigencia_fiscal, fin_vigencia_fiscal, codigo_condicion_venta,
    cuenta_corriente, codigo_usuario, codigo_categoria, razon_social,
    fecha_emision, fecha_pago, cantidad_deuda, tarifa, cantidad_pago,
    recargo, saldo, total_importe, pago_hasta, periodo_pago,
    codigo_usuario_sistema, codigo_estado, obs, codigo_cobrador,
    codigo_comision
)
SELECT
    origen.numero_comprobante,
    @codigo_punto_expedicion,
    NULLIF(TRIM(punto.punto_expedicion), ''),
    @codigo_sucursal,
    NULLIF(TRIM(sucursal.sucursal), ''),
    origen.codigo_serie,
    NULLIF(TRIM(serie.serie), ''),
    @codigo_tipo_comprobante,
    @codigo_timbrado,
    CAST(timbrado.numero_timbrado AS CHAR),
    timbrado.fecha_inicio,
    timbrado.fecha_fin,
    @codigo_condicion_venta,
    servicio.cuenta_corriente,
    servicio.codigo_usuario,
    categoria.codigo_categoria,
    origen.razon_social,
    origen.fecha_emision,
    DATE(origen.fecha_emision),
    0,
    CASE
        WHEN origen.cantidad_pago > 0
            THEN origen.total_importe / origen.cantidad_pago
        ELSE COALESCE(categoria.tarifa, 0)
    END,
    origen.cantidad_pago,
    0,
    0,
    origen.total_importe,
    NULL,
    NULL,
    @codigo_usuario_sistema,
    CASE WHEN origen.cantidad_pago = 0 THEN 3 ELSE 1 END,
    origen.obs,
    cobrador.codigo_cobrador,
    @codigo_comision
FROM tmp_comprobantes_sgc_origen origen
JOIN servicios servicio
  ON BINARY servicio.cuenta_corriente = BINARY origen.cuenta_corriente
 AND servicio.codigo_sucursal = @codigo_sucursal
JOIN categorias categoria
  ON categoria.codigo_categoria = origen.codigo_categoria
 AND categoria.codigo_sucursal = @codigo_sucursal
JOIN cobradores cobrador
  ON cobrador.codigo_cobrador = origen.codigo_cobrador
 AND cobrador.codigo_sucursal = @codigo_sucursal
JOIN series serie
  ON serie.codigo_serie = origen.codigo_serie
JOIN sucursales sucursal
  ON sucursal.codigo_sucursal = @codigo_sucursal
JOIN puntos_expedicion punto
  ON punto.codigo_sucursal = sucursal.codigo_sucursal
 AND punto.codigo_punto_expedicion = @codigo_punto_expedicion
JOIN timbrados timbrado
  ON timbrado.codigo_timbrado = @codigo_timbrado
 AND timbrado.codigo_empresa = sucursal.codigo_empresa
JOIN tipos_comprobante tipo
  ON tipo.codigo_tipo_comprobante = @codigo_tipo_comprobante
JOIN condiciones_venta condicion
  ON condicion.codigo_condicion_venta = @codigo_condicion_venta
JOIN usuarios_sistema usuario_sistema
  ON usuario_sistema.codigo_usuario_sistema = @codigo_usuario_sistema
JOIN comisiones comision
  ON comision.codigo_comision = @codigo_comision
WHERE NOT EXISTS (
    SELECT 1
    FROM comprobantes existente
    WHERE existente.numero_comprobante = origen.numero_comprobante
      AND existente.codigo_punto_expedicion = @codigo_punto_expedicion
      AND existente.codigo_sucursal = @codigo_sucursal
      AND existente.codigo_serie = origen.codigo_serie
      AND existente.codigo_tipo_comprobante = @codigo_tipo_comprobante
);

DROP TEMPORARY TABLE IF EXISTS tmp_comprobantes_sgc_origen;

